type SubscriptionStatus = 'active' | 'past_due' | 'canceled'

const TRANSITIONS: Record<
  SubscriptionStatus,
  readonly SubscriptionStatus[]
> = {
  active: ['past_due', 'canceled'],
  past_due: ['active', 'canceled'],
  canceled: [],
}

export const transition = (
  from: SubscriptionStatus,
  to: SubscriptionStatus,
): SubscriptionStatus => {
  if (!TRANSITIONS[from].includes(to)) {
    throw new Error(`transition ${from} vers ${to} interdite`)
  }
  return to
}

export const isAlreadyCharged = (
  invoiceId: string,
  charges: readonly { invoiceId: string }[],
): boolean => charges.some((charge) => charge.invoiceId === invoiceId)

export const chargeOnce = (
  invoiceId: string,
  charges: readonly { invoiceId: string }[],
): readonly { invoiceId: string }[] =>
  isAlreadyCharged(invoiceId, charges) ? charges : [...charges, { invoiceId }]

it('reactive un abonnement impaye apres son paiement', () => {
  expect(transition('past_due', 'active')).toBe('active')
})

it('refuse une transition non declaree', () => {
  expect(() => transition('canceled', 'active')).toThrow()
})

it('ne debite pas deux fois la meme facture', () => {
  const charges = chargeOnce('inv_1', [{ invoiceId: 'inv_1' }])

  expect(charges).toHaveLength(1)
})
